INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (7136,2,'guide','地狱火哨兵：治疗 [读条，只打断，击杀优先级 1]；暗言术：痛 [魔法] 伤害 dot、恢复 [魔法] 均可驱散。伤害 dot 取最高 ⇒ 2。｜静态证据: Heal, Shadow Word: Pain, Renew') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (16507,3,'guide','会 [冲锋] 随机目标，而且会抓潜行。 ｜静态证据: Charge') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (16594,1,'guide','[心灵震爆] 造成中等伤害，可打断；给自己和周围的怪施放 [真言术盾]、[抵抗暗影] 提高暗抗，对小怪施放 [治疗祷言] 造成 5000 左右群疗；注意进攻驱散和打断。 ｜静态证据: Prayer of Healing') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (16699,3,'guide','[上勾拳]、[顺劈斩]、[激怒] 提高攻速与伤害。 ｜静态证据: Uppercut') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (16700,3,'guide','同常站在一大组怪 (4 只以上) 面前、来回走动，免疫所有控场。与一群怪一起进入战斗时，会在其他小怪死亡时召唤 [邪兽人转化者]，因此在每一组怪中通常都默认第一优先击杀。给自己和周围的怪 [戒律光环] 提高招架格档机率，自身也会 [激怒] 提高攻速与伤害。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (16704,2,'guide','会对法系玩家施放抽蓝的 [蝰蛇钉刺]。 ｜静态证据: Incendiary Shot') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (16874,3,'guide','频繁 [灼烧] 目标造成中等火焰伤害并范围性 [火焰之雨]；注意打断，或干脆离开 [火焰之雨] 范围。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17269,3,'guide','频繁 [灼烧] 目标造成中等火焰伤害并范围性 [火焰之雨]；注意打断，或干脆离开 [火焰之雨] 范围。 ｜静态证据: Rain of Fire') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17280,3,'guide','[血肉撕咬] 会产生流血 dot，且 [狂怒嚎叫] 会提升自身伤害。 ｜静态证据: Carnivorous Bite, Furious Howl') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17309,2,'guide','地狱火哨兵：治疗 [读条，只打断，击杀优先级 1]；暗言术：痛 [魔法] 伤害 dot、恢复 [魔法] 均可驱散。伤害 dot 取最高 ⇒ 2。｜静态证据: Heal, Shadow Word: Pain, Renew') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17370,5,'guide','对当前目标 [盾牌猛击] 瞬发 2 秒击晕并驱散一个增益，中等伤害。瞬发控制 ⇒ 5（站长 2026-10-19 手动改档）。｜静态证据: Shield Slam(CTI=1, 2s)') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17371,3,'guide','频繁的 [腐蚀术] 和高额伤害的 [暗影箭]，还会以 [邪魔之能] 强化自己的宠物恶魔，尤其尾王前的两波，最好等 [邪魔之能] 消散了再开，免得控场成功前先被打死。 ｜静态证据: Corruption') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17395,3,'guide','会 [烈焰风暴] 读条大范围地板伤害（可打断）；召唤恶魔犬与魅魔施放 [沉默]、[法力吸取]、[魅惑]。高伤害 ⇒ 3。｜静态证据: Flamestrike(CTI=14), Summon Felhound Manastalker, Summon Seductress') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17397,3,'guide','会对坦克施放 [痛击]，这是二段三连击，可能对坦克造成瞬间大量伤害。由于本身就是双持速攻怪，瞬间七连击秒坦的事屡见不鲜，尽量风筝不要扛。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17398,5,'guide','[震荡猛击] 瞬发昏迷 5 秒、[践踏] 范围击退。瞬发硬控 ⇒ 5。｜静态证据: Concussion Blow(CTI=1), Stomp') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17414,3,'guide','影月技师：[自走炸弹]（白色地雷）靠近 8 码引爆，15 码内高额火焰伤害；[投掷炸弹] 中等火焰 AOE；对法系 [沉默]。｜静态证据: Silence, Throw Dynamite') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17427,3,'guide','在往血卫士伯鲁恩的天堂路上持续投放 [烈焰箭]，在地上生成一摊火焰。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17429,3,'guide','会对自身施放 [狂乱]，使攻速提高 60%；[冲锋] 随机目标、[失控] 清空仇恨转移目标。 ｜静态证据: Charge, Enrage') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17464,3,'guide','伤害很高但可被缓速，[致死打击]。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17465,3,'guide','免疫所有控场，对目标 [破甲攻击]、对周围小怪 [战斗怒吼] 增伤。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17478,3,'guide','固定组合，前者对随机目标 [恐惧]（读条可打断）、[暗影箭] 使玩家逃跑，后者免疫控场。读条控制 ⇒ 3。｜静态证据: Fear(CTI=4)') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17491,5,'guide','以潜行状态存在，[肾击] 瞬发昏迷 5 秒，脆皮被一套秒杀。瞬发硬控 ⇒ 5。｜静态证据: Kidney Shot(CTI=1), Poison') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17670,3,'guide','这两种怪是固定组合，驯犬者免疫控场，会 [多重射击]，并周期性驱散周围小怪的减益效果；军犬则会 [狂怒嚎叫] 增伤，[血肉撕咬] 造成高额物理伤害，清这波怪时注意注意维持控场缓速的减益效果。 ｜静态证据: Volley') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17671,3,'guide','免疫控场但可缓速。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17693,3,'guide','会 [冲锋] 随机目标，而且会抓潜行。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17694,3,'guide','会 [恐惧]（读条可打断），还有大范围 [火焰之雨] 务必打断或躲开。读条控制 ⇒ 3。｜静态证据: Fear(CTI=16), Rain of Fire') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17695,3,'guide','以潜行状态存在，会 [闷棍]、[背刺] 偷袭。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17721,3,'guide','[投网] 定身玩家后，对他所在位置投掷炸弹 [轰炸]。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17722,3,'guide','[冰霜新星] 可驱散；寒冰箭、[暴风雪] 可打断。 ｜静态证据: Blizzard') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17723,3,'guide','门神，[击退] 附带高额物理伤害、[蘑菇凋零] 缓速目标，是疾病可驱散、[生长] 每 20 秒提高 15% 伤害，能叠加 10 次。幽暗沼泽领主的伤害尤其高，可以用 [击退] 风筝一下。 ｜静态证据: Fungal Decay, Trample') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17725,3,'guide','本身伤害就高，还自带狂暴 [野性成长]，提高 50% 物理伤害，但可缓速。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17729,2,'guide','[蝰蛇钉刺] 抽蓝，即时驱散。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17730,1,'guide','[圣光术]、[治疗祷言] 造成巨额治疗，务必打断。[恢复] 可进攻驱散。 ｜静态证据: Holy Light, Prayer of Healing') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17731,3,'guide','对非当前目标 [惊骇]（读条可打断/驱散），恐惧跑得飞快小心引怪。读条控制 ⇒ 3。｜静态证据: Psychic Horror(CTI=16)') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17732,2,'guide','不停地 [毒液喷吐]，是中毒可驱散或打断。 ｜静态证据: Poison Spit') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17771,3,'guide','分成三种法系，读条都会造成中等魔法伤害，其中火法型威胁最大。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17801,3,'guide','[闪电箭] 可打断；[奥术闪耀] 可驱散魔法 dot；[恐惧] 20 码 4 秒群恐为读条可打断。读条控制 ⇒ 3。｜静态证据: Fear(CTI=4), Arcane Flare') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17803,3,'guide','[冰霜震击] 会造成单体高额冰霜伤害并缓速 8 秒，[音素爆破] 对近战范围小额 AOE 且沉默 10 秒，两者都是魔法、皆可驱散；[治疗术] 注意打断。 ｜静态证据: Heal, Sonic Burst') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17815,3,'guide','虽然是黄名怪，但会主动攻击萨尔，而且不给声望。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17816,3,'guide','小的会 [穿刺] 目标，使受到的物理伤害提高 15%，可叠加；大的会 [力量衰减] 使力量降低 25%。 ｜静态证据: Piercing Jab') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17819,3,'guide','对目标 [致死打击]。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17820,3,'guide','[多重射击] AOE 和对当前目标 [驱散射击] 使其困惑 4 秒。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17833,5,'guide','敦霍尔德看守：队长战 ''优先击杀敦霍尔德看守''；[治疗] 读条、[心灵尖啸] 瞬发群恐 4 秒、[暗言术：痛] 可驱散。瞬发群恐+留场回血 ⇒ 5。｜静态证据: Psychic Scream(CTI=1), Heal, Shadow Word: Pain') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17860,3,'guide','随机施放 [暗言术痛] 可驱散、[驱散魔法]、[心灵尖啸] 群恐（读条可打断）。静态表仅见近战技能，与攻略描述不符 ⇒ 3。★待复核｜静态证据: Sinister Strike, Backstab') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17871,2,'guide','对玩家施放 [疼痒孢子] 疾病伤害 dot 可驱散；[蘑菇再生] 读条治疗可打断/偷取；[过敏] 打喷嚏断法击退。dot+治疗取最高 ⇒ 2。｜静态证据: Itchy Spores, Fungal Regrowth') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17893,3,'guide','位于尾王房右手边的友方 NPC，完成营救事件后对话给予 [拜特的印记] 增益效果，提高 110 自然抗性与 5% 所有属性。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17938,2,'guide','施放 [献祭]，可驱散；丢掷 [烈性炸药]，使 30 码内玩家受到火焰伤害。 ｜静态证据: Immolate') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17940,3,'guide','[火焰之雨] 造成中等火焰伤害，可以打断或干脆躲开。 ｜静态证据: Rain of Fire') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17957,5,'guide','[破甲攻击]、[顺劈斩]；[破胆怒吼] 瞬发群恐 6 秒并转头打最高威胁。瞬发群恐+仇恨重置 ⇒ 5。｜静态证据: Frightening Shout(CTI=1)') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17958,3,'guide','门神怪，免疫控场但可缓速，对坦克造成高额伤害，一般会风筝走一个。[盾牌猛击] 会使目标昏迷 2 秒，[法术反射] 有 50% 机率反弹受到的法术。 ｜静态证据: Shield Slam') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17960,5,'guide','[智力衰减] 智力 -25%、[支配] 瞬发心控一名玩家 10 秒（不可驱散）。瞬发控制 ⇒ 5。★待确认｜静态证据: Domination(CTI=1), Decayed Intellect') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17961,3,'guide','[闪电箭] 可打断；群体定身 8 秒的 [纠缠根须] 和指定一个区域施放的 [落雷之云] 两者连招会死人，务必及时驱散定身。 ｜静态证据: Entangling Roots') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17962,3,'guide','[残废术] 降低攻速与移速，可以打断或驱散。低血量时会 [激怒] 提高攻速。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17964,3,'guide','当盘牙纳迦进入战斗，会驱使附近的黄名荒土怪也一起参战；荒土工人会对目标叠加流血 dot [撕裂]，荒土奴隶会施放 [寒冰箭] 和 [冰霜新星]，不过一但盘牙监工死亡，他们就会脱战离开。 ｜静态证据: Rend') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17993,3,'guide','[水晶打击] 是近战攻击但是造成奥术伤害，所以对坦也不低；[法术反射] 可以在 8 秒内反射 4 次法术。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (17994,3,'guide','标记一名玩家 [猎鹰的召唤] 使血鹰无视仇恨锁定攻击，[冲锋] 击倒后 [猛扑] 击晕、[摔拌] 缓速；本体无读条控制。⇒ 3。★瞬发锁仇型待确认｜静态证据: Call of the Falcon, Wing Clip') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18058,2,'guide','地狱火哨兵：治疗 [读条，只打断，击杀优先级 1]；暗言术：痛 [魔法] 伤害 dot、恢复 [魔法] 均可驱散。伤害 dot 取最高 ⇒ 2。｜静态证据: Heal, Shadow Word: Pain, Renew') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18092,3,'guide','[致死打击]、[冲锋] 远处玩家，造成轻微伤害并击退。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18093,5,'guide','[震荡猛击] 重击目标昏迷 5 秒（瞬发）；[清洁术] 驱散小怪减益；[快速治疗] 读条可打断。瞬发控制 ⇒ 5。★与 23179/23180 同型待确认') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18094,2,'guide','[毒蛇钉刺] 中毒可驱散；[震荡射击] 3 秒 50% 缓速，是魔法可驱散。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18311,3,'guide','[灵魂打击] 附带致死效果，对远处玩家 [冲锋] 击倒昏迷 2 秒，低血量时还会 [激怒] 提高伤害与攻速。 ｜静态证据: Charge') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18312,2,'guide','施放造成中等伤害的 [献祭] DOT，且虚灵巫师相似，会召唤 [虚灵怨魂]。 ｜静态证据: Immolate, Summon Ethereal Wraith') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18313,3,'guide','[减速]、[奥术飞弹]、召唤会 [魔爆术] 的虚数魔。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18314,5,'guide','[凿击] 瞬发昏迷 4 秒，昏迷期间无视被凿目标转打其他人。瞬发控制+仇恨转移 ⇒ 5。｜静态证据: Gouge(CTI=1), Phantom Strike') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18315,3,'guide','会使用 [变羊术]（读条可打断/可驱散）。读条控制 ⇒ 3。｜静态证据: Polymorph(CTI=16)') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18317,3,'guide','会对小怪施放治疗量极高的 [治疗术]（读条可打断）；另有瞬发群体治疗 [神圣新星]。瞬发治疗 ⇒ 3。★口径边界待确认（小瞬发 HoT 不算）｜静态证据: Heal(CTI=22), Holy Nova(CTI=1)') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18318,3,'guide','[法术反射] 持续 6 秒。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18321,5,'guide','[击晕] 瞬发眩晕当前仇恨目标并转移仇恨。瞬发控制+仇恨转移 ⇒ 5。｜静态证据: Talon of Justice(CTI=1)') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18322,3,'guide','门神怪，对坦伤害极高，只吃昏迷控场。场上同时存在二只时，一只死亡另一只 [激怒]。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18323,3,'guide','对坦伤害偏高，免疫缴械和昏迷以外的控场，并会 [雷霆一击] 近战范围缓速，是魔法可驱散。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18325,3,'guide','死后生成一个 [幽灵]，移动速度缓慢，但近身后造成高额伤害，免疫攻击，几秒后自动消失；被盯上绕道走。 ｜静态证据: Fear') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18328,3,'guide','对目标与其正面 [奥术闪电]（读条可打断，弹射+群体沉默），坦克使怪背对队友。读条控制 ⇒ 3。｜静态证据: Arcane Lightning(CTI=16)') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18331,3,'guide','会施放造成中等伤害的 [暗言术痛] DOT，并对 30 有码内的蓝职业施放 [法力燃烧]，点一次最高能烧掉一万点法力值。除此之外，虚灵暗法师还自带一个 [吸血光环]，会在造成近战攻击的同时治疗自身。后二者法术的存在导致他们必需被优先击杀，而且最好全程晕缓控制，让他放不出法术也无法攻击坦克。 ｜静态证据: Shadow Word: Pain') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18404,3,'guide','[奥术飓风] 是一个 30 码范围的奥术版旋风斩。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18405,3,'guide','[奥术冲击] 对目标造成中等伤害并击退；[奥术箭雨] 和 [魔爆术] 两者皆为范围 AOE 且可打断。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18419,3,'guide','[管理员之怒] 造成高额伤害，但可打断，被反制后会改用瞬发的 [自然震击] 但伤害就低得多；[昏迷迫近] 会使移速降低 70%，是中毒可驱散，持续时间结束后会使该玩家沉睡 5 秒。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18422,1,'guide','植物学家会对魔花施放 [自然之怒]，使它的攻速伤害翻倍；还会施放 [枯木逢春]、[愈合] 治疗小怪，可打断或驱散。 ｜静态证据: Regrowth') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18431,3,'guide','虚灵航标：沙法尔战 ''全程优先击杀 [虚灵航标]''（否则变成学徒）；[奥术箭]、自毁召唤 [虚灵学徒]。｜静态证据: 沙法尔战攻略（优先击杀指令）') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18497,3,'guide','免疫控场，并以 [飓风打击] 造成中等物理伤害并击退附近的玩家。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18498,3,'guide','[防护光环] 提供周围小怪极高护甲、并会使用有法术反制效果的 [盾击]。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18500,1,'guide','[特效治疗] 治疗小怪，可打断。 ｜静态证据: Major Heal') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18501,2,'guide','对怪施放 [灵魂复仇]，提高攻速与移速，还会 [蝰蛇钉刺] 抽蓝。 ｜静态证据: Serpent Sting, Spirit Vengeance') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18503,3,'guide','免疫控场，出现后立即引导 5 秒施法，对一名玩家施放 [占据] 心控他，持续一分钟、或将被心控的玩家的血量削减到 50% 以下方能脱控。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18506,3,'guide','桥上的隐形怪，现形后 5 秒会 [暴怒] 自爆击退 8 码内玩家，小心别被弹下桥。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18521,3,'guide','周期性地清空威胁值列表、转移仇恨目标，另外因为掉落附魔靴子敏捷配方而成为单刷热门。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18524,3,'guide','周期性地 [发怒] 提高攻速。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18633,1,'guide','[治疗术]，可打断。 ｜静态证据: Heal') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18636,5,'guide','击败一王后刷新，潜行游荡，[偷袭]、[凿击] 瞬发偷袭。按同型（凿击=瞬发硬控）从严 ⇒ 5。★无静态数据待确认') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18637,3,'guide','[精神鞭笞]（引导）与 [暗言术痛] 伤害相当高，后者魔法可驱散。高伤害+dot 取最高 ⇒ 3。★待确认｜静态证据: Mind Flay(引导), Shadow Word: Pain') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18638,3,'guide','当血量降至 20% 时会施放 [野兽之形] 变身为怪兽，可进攻驱散。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18639,3,'guide','会 [洗脑] 心控玩家，可打断。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18640,2,'guide','自带 [魔甲术] 吸收暗影伤害，可進攻驱散；对玩家施放 [暗影箭]、[腐蚀之种]，后者应当尽早驱散或爆炸前远离队友。 ｜静态证据: Seed of Corruption') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18702,2,'guide','奥金尼通灵师：[腐蚀之种] 不驱散会爆炸（可驱散 dot）、[暗影愈合]（可打断）、[吸取灵魂]。｜静态证据: Seed of Corruption, Shadow Mend') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18794,3,'guide','高危型背法杖者施 [降服人类]，引导 6 秒昏迷（可打断/驱散）。引导控制 ⇒ 3。★无静态数据（脚本）') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18796,5,'guide','门神免疫控场；[上勾拳]、[致死打击]；[破胆怒吼] 瞬发群恐 6 秒并转头打最高威胁。瞬发群恐+仇恨重置 ⇒ 5。｜静态证据: Frightening Shout(CTI=1), Uppercut') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18830,3,'guide','无视仇恨目标，[凝视] 特定玩家追击他并提高攻速。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18848,3,'guide','会对当前目标施放 [缴械] 和造成额外伤害的 [恶意印记]、对近战范围 [暗影新星] AOE。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18894,3,'guide','可控场缓速但无法被奴役，对坦高额物理伤害，务必一次只拉一只；而且还会 [冲锋] 和 [上勾拳]，一套连招巨额伤害，脆皮职业直接升天。另外要注意这种怪的攻击范围很大，似乎有 15 码。 ｜静态证据: Uppercut') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (18934,3,'guide','只在萨尔逃离段刷新。会 [霜甲术]、[冰锥术]、[火球术] 和 [变羊术]（读条可打断，变羊可驱散）。读条控制 ⇒ 3。★无静态数据（脚本）') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (19166,5,'guide','[击倒] 当前目标昏迷 2 秒（瞬发，脚本/EventAI）；半血呼救引怪。瞬发硬控 ⇒ 5（站长 2026-10-19 手动改档）。｜静态证据: 无（脚本流程）') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (19167,3,'guide','本身伤害就高，还会 [旋风斩]、对当前目标 [恒星之击] 重击造成高额伤害并附带致死效果。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (19168,3,'guide','[灼烧]、[灼热日光] 造成火焰伤害，并会使其目标 [熔化护甲]；对自身施加 [火焰之盾] 持续地 5 码范围 AOE，可进攻驱散或偷取，法师偷取它们能增加不少伤害。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (19218,3,'guide','看守者盖罗基尔（能源舰看门人）：[锯齿利刃] 4500 物理+8 秒 DOT、[暗影能量] 攻速+115% 可打断、[流动机蒸汽] 中毒可驱散。高伤害 ⇒ 3。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (19306,3,'guide','会 [法力燃烧] 抽取 30 码内玩家的蓝，死亡时会 [魔爆术] 10 码爆炸，近战远离。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (19307,5,'guide','[心灵尖啸] 瞬发群恐 4 秒、[死亡缠绕] 瞬发恐惧；[无力诅咒] 诅咒、[暗影之拥] 魔法可驱散。瞬发群恐 ⇒ 5。｜静态证据: Psychic Scream(CTI=1), Death Coil(CTI=1)') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (19428,3,'guide','正面群体攻击，坦克使其保持背对人群。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (19429,3,'guide','[冲锋] 第二仇恨并击倒，造成中等伤害。 ｜静态证据: Carnivorous Bite, Sonic Charge') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (19486,3,'guide','不停在脚下丢掷 [毒性之瓶]，近战要持续移动；[火息药水] 会正面喷火造成高額火焰傷害。 ｜静态证据: Vial of Poison') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (19507,3,'guide','[死亡凋零] 对一名玩家所在地点指定 8 码范围的高额伤害 AOE，要尽速离开。与收割员、草药学家的小怪组合能组成一套秒杀。 ｜静态证据: Summon Lasher Beast') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
