INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (19509,3,'guide','[变形术] 读条 16 把玩家变花（可打断/驱散）、[枯萎之触] 可驱散。读条控制 ⇒ 3。｜静态证据: Polymorph(CTI=16), Wilting Touch') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (19511,5,'guide','[肾击] 瞬发昏迷 5 秒，[致命药膏] 中毒可驱散。瞬发硬控 ⇒ 5。｜静态证据: Kidney Shot(CTI=1), Deadly Poison') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
