INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (19633,1,'guide','[神圣愤怒] 使小怪提高 295 法伤，可进攻驱散或偷取；[心灵震爆]、[强效治疗术] 均可打断，务必打断后者。 ｜静态证据: Greater Heal') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (19710,3,'guide','看守者埃隆汉（能源舰看门人）：[锤击] 昏迷 6 秒、[风钻] 15 码每秒 2500×8 秒、[暗影能量] 可打断、[流动机蒸汽] 中毒可驱散。高伤害 ⇒ 3。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (19735,3,'guide','物理伤害偏高但走路较慢，同样会 [击倒]，并会以 [充能之拳] 强化自身，使每次近战攻击都附加造成中等奥术伤害的近战范围 AOE，务必打断，如果没打断就风筝起来吧。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
