INSERT INTO `tbccharacters`.`ai_playerbot_priority_target` (`entry`,`priority`,`source`,`reason`) VALUES (20059,3,'guide','[奥术新星] 对 10 码内玩家造成中等奥术伤害，并治疗小怪。[驱散魔法] 能主动驱散小怪身上的 debuff。并且召唤会 [奥术箭雨] 的 [奥术仆从]，其死亡时会 [魔爆术]，人宠都是单技能伤害不高、但叠加起来就可观了。') ON DUPLICATE KEY UPDATE `priority`=VALUES(`priority`),`source`=VALUES(`source`),`reason`=VALUES(`reason`);
