-- ============================================================================
-- 卡布魔兽 bot 相关 SQL：重点小怪优先级表（195）
-- 名单来源：dev/tbc五人本攻略.md 的 13 处「重点小怪」章节（人工逐条审计）
-- 口径（2026-10-19 站长修正版）：
--   5 = 任何情况必须立刻转火击杀，有瞬发控制技能，瞬发高伤害，容易导致倒t和其他灭团技能。
--   3 = 有读条类可打断的控制技能、瞬发治疗、不可驱散伤害类 dot、本身高伤害或者有高伤害技能。
--       优先控制，如果控制不够则优先击杀
--   2 = 有伤害类 dot（站长裁定：标记是全局的，所有可驱散类型的 dot 一律 2）
--   1 = 有读条类治疗，只需要打断；打断好就不用优先击杀（⇒ 击杀优先级1）
--   4 = 优先控制，最后击杀（吃控制，不够造成威胁，并且血量过高没有击杀效率），不给小怪主动标记4，只依靠手动标记。
--   0 = 已废弃：数据层不再使用 0（加载器只读 priority>0）；“最后处理”请用 1/2/3/5 表达或移出本表。
--   通用规则：吃控制的怪，控制能替我们处理 ⇒ 优先级降到最后，不能打醒控制，如果一个怪物有多个档，取最高。
--   判档执行：多特征取最高档；控制类按施法方式分——瞬发(CastingTimeIndex=1 且非引导) ⇒ 5，
--       读条/引导 ⇒ 3；本表不产出 4；0 档 = 无需动作（加载器按 priority>0 过滤）。
-- 静态/幂等 SQL；INSERT ... ON DUPLICATE KEY UPDATE 覆盖旧值。
-- 存档：旧档位（git HEAD）为 1/3 两档；本表按 2026-10-19 口径（v2 修正版）逐条审计重排；
--       2026-10-19 修订：17370/19166=5 为站长手动改档；恢复 17540=3；末尾加白名单清理
--       （审计与争议记录：_agent_tmp/报告_重点小怪优先级表_20261019.md；
--        v1 定稿备份：_agent_tmp/audit195/195_v1_final.sql）。
-- ============================================================================
SET NAMES utf8mb4;
USE `tbccharacters`;

CREATE TABLE IF NOT EXISTS `tbccharacters`.`ai_playerbot_priority_target` (
  `entry`    INT UNSIGNED     NOT NULL,
  `priority` TINYINT UNSIGNED NOT NULL,
  `source`   VARCHAR(16)      NOT NULL,
  `reason`   VARCHAR(255)     NOT NULL,
  PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- ---------------------------------------------------------------------------
-- 幂等清理（2026-10-19 站长口径：数据层不再用 0）：
--   本表只保留上面白名单里的 guide 行；被移出名单的旧行（含 priority=0 的残留）一律删除。
--   手工行（source='manual'）不受影响。
-- ---------------------------------------------------------------------------
DELETE FROM `tbccharacters`.`ai_playerbot_priority_target`
 WHERE `source` = 'guide' AND `entry` NOT IN (7136,16507,16594,16699,16700,16704,16874,17269,17280,17309,17370,17371,17395,17397,17398,17414,17427,17429,17464,17465,17478,17491,17540,17670,17671,17693,17694,17695,17721,17722,17723,17725,17729,17730,17731,17732,17771,17801,17803,17815,17816,17819,17820,17833,17860,17871,17893,17938,17940,17957,17958,17960,17961,17962,17964,17993,17994,18058,18092,18093,18094,18311,18312,18313,18314,18315,18317,18318,18321,18322,18323,18325,18328,18331,18404,18405,18419,18422,18431,18497,18498,18500,18501,18503,18506,18521,18524,18633,18636,18637,18638,18639,18640,18702,18794,18796,18830,18848,18894,18934,19166,19167,19168,19218,19306,19307,19428,19429,19486,19507,19508,19509,19511,19512,19632,19633,19710,19735,19843,20059,20988,20990,21126,21127,21128,21695,22081,23175,23176,23177,23178,23179,23180);
